        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30643.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30643.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30643.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else {
            return true;
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30643.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnClick = function(row, colid) {
    try {
        const CHAR_NM = dts_ComDisclsPerson.getCellData(row, "CHRG_NM"); // 담당자명
        let ISUR_NM = dts_ComDisclsPerson.getCellData(row, "COM_ABBRV"); // 회사명
        let ISURCD = dts_ComDisclsPerson.getCellData(row, "ISUR_CD"); // 회사명
        const JOBTITL = dts_ComDisclsPerson.getCellData(row, "JOBTITL_NM"); // 직위
        const TLENO = dts_ComDisclsPerson.getCellData(row, "CELLPHONE_NO"); // 전화번호

        txb_sel_nm.setValue(CHAR_NM);
        txb_sel_isur_nm.setValue(ISUR_NM);
        txb_hdn_isur_cd.setValue(ISURCD);
        if (JOBTITL === "") {
            txb_jobtitl_nm.setValue("-");
        } else {
            txb_jobtitl_nm.setValue(JOBTITL);
        }
        if (TLENO === "") {
            txb_tel_no.setValue("-");
        } else {
            txb_tel_no.setValue(TLENO);
        }
        chb_insert_yn.setValue(0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30643.grd_Grid_OnClick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
