    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30643.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await scwin.alert_error2(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30643.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
        await $c.win.alert(msg);
        dts_Save.removeAll();
        txb_sel_isur_nm.setValue('');
        chb_insert_yn.setValue(0);
        await scwin.setHeader();
        const f_fn_search = $c.frame.path("../").fn_Search;
        f_fn_search();
        // frame.CloseFrame();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30643.trs_Save_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setHeader
 * @description set Header 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setHeader = async function() {
    const sbmOptions = {
        id : "sbm_dts_Save",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "dts_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    dts_Save.insertRow();
};

/**
 * @method
 * @name search
 * @description 담당자 검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (txb_isur_cd.getValue() === '') {
        await $c.win.alert("[회사]를 선택해 주십시오");
        txb_com_abbrv.focus();
        return;
    }
    url += "&ISUR_CD=" + txb_isur_cd.getValue();
    url += "&EDU_KIND_CD=";
    url += "&YYYY=";
    url += "&EMP_NO=";
    url += "&DEP_CD=";
    url += "&CHRG_NM=" + txb_chrg_nm.getValue();
    url += "&SCREN_ID=" + "ULDSTF30643.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions = {
        id : "sbm_dts_ComDisclsPerson",
        action : "/ListedCompany.do",
        ref : "",
        target : "dts_ComDisclsPerson=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    if (txb_hdn_isur_cd.getValue() === '') {
        if (chb_insert_yn.getValue() === 'Y') {
            await $c.win.alert("[회사코드]를 입력해 주십시오");
        } else {
            await $c.win.alert("[회사]를 조회해 주십시오");
        }
        txb_hdn_isur_cd.focus();
        return;
    }
    if (txb_sel_nm.getValue() === '') {
        if (chb_insert_yn.getValue() === 'Y') {
            await $c.win.alert("[성명]를 입력해 주십시오");
        } else {
            await $c.win.alert("[성명]를 선택해 주십시오");
        }
        txb_sel_nm.focus();
        return;
    }
    if (cmb_sel_priz_rec.getValue() === '') {
        await $c.win.alert("[표창여부]를 입력해 주십시오");
        cmb_sel_priz_rec.focus();
        return;
    }
    if (txb_profs_ahth_no.getValue() === '') {
        await $c.win.alert("[인증번호]를 입력해 주십시오");
        txb_profs_ahth_no.focus();
        return;
    }
    if (txb_profs_ahth_rnd.getValue() === '') {
        await $c.win.alert("[인증회차]를 입력해 주십시오");
        txb_profs_ahth_rnd.focus();
        return;
    }
    if (edt_ahth_dd.getValue() === '') {
        await $c.win.alert("[인증시기]를 입력해 주십시오");
        edt_ahth_dd.focus();
        return;
    }
    if (cmb_sel_ahth_yn.getValue() === '') {
        await $c.win.alert("[인증여부]를 입력해 주십시오");
        cmb_sel_ahth_yn.focus();
        return;
    }
    if (confirm('저장 하시겠습니까?')) {
        scwin.gLastJob = "저장";
        dts_Save.setCellData(1, "PROFS_CHRG_YN", scwin.getCheckboxData(chb_insert_yn));
        trs_Save.KeyName = "toinb_dataid4";
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/ListedCompany.do",
            ref : "dts_Save",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name check
 * @description check 처리
 * @returns {void}
 * @hidden N
 */
scwin.check = function() {
    if (chb_insert_yn.checked === true) {
        let ISUR_NM = txb_com_abbrv.getValue(); // 회사명
        let ISURCD = txb_isur_cd.getValue(); // 회사명

        txb_sel_isur_nm.setValue(ISUR_NM);
        txb_hdn_isur_cd.setValue(ISURCD);

        // txb_sel_nm.value = "";
        // txb_jobtitl_nm.value ="";
        // txb_tel_no.value = "";

    }
};

/**
 * @method
 * @name getCheckboxData
 * @description get Checkbox Data 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getCheckboxData = function(obj) {
    if (obj.checked) {
        return 'N';
    } else {
        return 'Y';
    }
};

/**
 * @method
 * @name alert_error2
 * @description 저장 에러 발생 시
 * @param {*} dtsObj dtsObj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.alert_error2 = async function(dtsObj) {
    const USER_DEFINE = new Array("INTERNAL", "UNDEFINED", "APP_COMPONENT", "BIZ_COMPONENT", "ACTION", "CORE_FRAMEWORK", "WEB_FRAMEWORK", "INFO");
    for (let i = 0; i < USER_DEFINE.length; i++) {
        const errorCount = dtsObj.SrvErrCount(USER_DEFINE[i]);
        let j;
        for (j = 0; j < errorCount; j++) {
            if (dtsObj.SrvErrCode(USER_DEFINE[i], j) === '0') {
                // '0' 임의로 떨군 INFO 메시지
                await $c.win.alert(dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            } else {
                // 기존 에러 메시지
                await $c.win.alert("[CODE: " + dtsObj.SrvErrCode(USER_DEFINE[i], j) + "] " + dtsObj.SrvErrMsg(USER_DEFINE[i], j));
            }
        }
    }
};
